-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"f7ca0051-a6b6-4707-b6c9-1ef7ab38ea77","n":1,"title":"الخطاب العلمي","passage":"يعتمد الخطاب العلمي على تحديد المفهوم ودقة الملاحظة وبيان طريقة الوصول إلى النتيجة، لا على كثرة المصطلحات وحدها. في نص ضاديوم المستقل: «قارنت مجموعة نمو نبتتين تحت شروط موضحة وسجلت اختلاف النتائج»، ويحتاج القارئ معرفة الشروط والبيانات قبل تعميم الملاحظة. ليس هذا اقتباسًا من كتاب رسمي.","question":"ما الذي يجعل نتيجة الخطاب العلمي قابلة للمراجعة؟","correct":"توضيح الطريقة والبيانات","wrong":["استعمال استعارة فقط","إخفاء شروط المقارنة","الاستغناء عن المصدر"],"practice":"اكتب فقرة علمية قصيرة تصف ملاحظة حقيقية من مصدر موثوق مع المتغيرات وحدود الاستنتاج.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"f7ca0051-a6b6-4707-b6c9-1ef7ab38ea77","n":2,"title":"اسم التفضيل","passage":"يأتي اسم التفضيل في الغالب على وزن «أفعل» مثل «أكبر»، ويختلف استعماله بحسب تجرده من أل والإضافة وغير ذلك. في «هذه المسألة أسهلُ من سابقتها» نُقارن مسألتين في صفة السهولة، ولا نفترض من الصيغة وحدها تفضيلًا علميًا مثبتًا.","question":"ما اسم التفضيل في «المسألة أسهل من سابقتها»؟","correct":"أسهل","wrong":["المسألة","سابقتها","من"],"practice":"صغ أربع جمل مقارنة صحيحة، ثم بين المفضَّل والمفضَّل عليه في كل جملة.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"f7ca0051-a6b6-4707-b6c9-1ef7ab38ea77","n":3,"title":"الخطاب الأدبي","passage":"يستخدم الخطاب الأدبي صورًا ولغةً موحية وبناءً يثير استجابة القارئ، لكنه لا يهمل المعنى أو الاتساق. في صورة أصلية «ابتسمت النوافذ عند الصباح» استعارة تشخص النوافذ؛ ولا يعني ذلك وقوع الابتسام حرفيًا. نفصل بين الشاهد الفني والتفسير الشخصي.","question":"أي أسلوب في «ابتسمت النوافذ»؟","correct":"استعارة قائمة على التشخيص","wrong":["وصف علمي حرفي","حساب عددي","نهي صريح"],"practice":"قارن فقرة علمية وفقرة أدبية من إنشائك عن موضوع واحد وحدد أثر اللغة في كل منهما.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"f7ca0051-a6b6-4707-b6c9-1ef7ab38ea77","n":4,"title":"الخبر وأضربه","passage":"قد يُلقى الخبر ابتدائيًا بلا مؤكد عندما لا يُتوقع إنكار المخاطب، وطلبيًا بمؤكد مناسب عندما يتردد المخاطب، وإنكاريًا بما يناسب شدة الإنكار في السياق. في «إنَّ القراءةَ نافعةٌ» تظهر أداة توكيد نحوية، لكن تحديد الضرب البلاغي النهائي يحتاج حال المخاطب.","question":"ما أداة التوكيد في «إن القراءة نافعة»؟","correct":"إنَّ","wrong":["القراءة","نافعة","في"],"practice":"اكتب خبرًا واحدًا بثلاث صيغ تتفاوت في التوكيد، ثم افترض مقامًا مناسبًا لكل منها.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"f7ca0051-a6b6-4707-b6c9-1ef7ab38ea77","n":5,"title":"مهارة الربط بين الأفكار","passage":"يتماسك النص عندما ترتبط الفكرة التالية بسابقتها بعلاقة سبب أو نتيجة أو إضافة أو استدراك، لا بمجرد تكرار أدوات الربط. في مثال أصلي «تأخر وصول الكتب؛ لذلك تغير موعد النشاط، لكن الفريق احتفظ بهدف القراءة». تربط «لذلك» النتيجة، و«لكن» الاستدراك.","question":"ما العلاقة التي تعبر عنها «لذلك» في المثال؟","correct":"النتيجة المترتبة على سبب","wrong":["حرف نداء","سؤال عن مكان","قسم"],"practice":"اكتب فقرة من ست جمل تستخدم علاقات السبب والنتيجة والاستدراك دون تكرار غير لازم.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":1,"title":"مقدمة عن الحضارة الإسلامية","passage":"دراسة مظاهر المعرفة في الحضارة الإسلامية تحتاج مراعاة تعاقب الأزمنة وتنوع المدن والمجالات واللغات، والتحقق من نسبة الكتب إلى مؤلفيها. في مثال ضاديوم المستقل يضع طالب جدولًا يميز بين تاريخ المؤلف وموضوع المخطوط ومصدر المعلومات؛ ولا يمثل الجدول شهادة تاريخية بذاته.","question":"ما الذي يدعم وصف إنجاز علمي تاريخي؟","correct":"عمل موثق بتاريخ وسياق ومصدر","wrong":["حكاية بلا مرجع","اختراع اسم كتاب","تعميم عن كل العصور"],"practice":"كوّن بطاقة لعمل علمي تراثي موثق تتضمن المؤلف والتاريخ التقريبي والمجال والمصدر.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":2,"title":"صيغ التعجب","passage":"من صيغ التعجب القياسية «ما أفعَلَه!» و«أفعِلْ به!» وفق شروط صرفية ونحوية. في «ما أجملَ التنظيمَ!» نعبر عن الإعجاب، ولا نعد كل جملة تبدأ بـ«ما» تعجبًا؛ فقد تستخدم «ما» للاستفهام أو النفي أو غيرهما.","question":"ما صيغة التعجب في «ما أجمل التنظيم»؟","correct":"ما أفعلَه","wrong":["أداة شرط جازمة","اسم موصول","نفي بلم"],"practice":"اكتب أربع جمل تعجبية واضبط التعجب القياسي، ثم قارنها بسؤال يبدأ بـ«ما».","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":3,"title":"موضوعات الطب","passage":"حين نقرأ نصًا في تاريخ الطب نفرق بين وصف الممارسة في عصرها وبين سلامتها وفق المعرفة الطبية الحالية. مثال مستقل يراجع متعلم مخطوطًا يذكر وصفة، ثم يسأل عن سياقها التاريخي ولا يجربها لعلاج أحد. لا يقدم تدريب ضاديوم نصيحة طبية فردية أو علاجًا.","question":"ما التصرف الآمن عند مصادفة وصفة في مخطوط تاريخي؟","correct":"دراستها تاريخيًا دون استخدامها علاجًا","wrong":["تجريبها بلا تقييم","تعميم فعاليتها","القول إن كل وصفة حديثة"],"practice":"ابحث في مصدر موثوق عن تطور ممارسة طبية عبر عصرين مع فصل التاريخ عن التوصيات الحديثة.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":4,"title":"الإنشاء","passage":"الكلام الإنشائي لا يقتصر على الإخبار، بل يشمل الطلب والأمر والنهي والاستفهام والتعجب وغيرها بحسب الصيغة. في «هل فهمتَ الفكرة؟» استفهام، وفي «اكتبْ الملاحظة» أمر، ويُعرف غرض كل صيغة من المقام والمخاطب.","question":"ما نوع «هل فهمت الفكرة؟»؟","correct":"استفهام طلبي","wrong":["خبر ابتدائي","اسم فاعل","مفعول به"],"practice":"صغ ست جمل إنشائية متنوعة وناقش سبب اختلاف الغرض بين صيغها.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":5,"title":"الطب علم وعمل","passage":"يجمع العمل العلمي بين المعرفة والتطبيق المنضبط وأخلاقيات المسؤولية، لكن عنوان «الطب علم وعمل» لا يسمح لنا بنسبة حجة بعينها إلى كاتب مجهول. في مثال مستقل يراجع فريق تثقيف صحي دقة لوحة معلومات عامة قبل نشرها، وهو تدريب على التوثيق لا إجراء علاجي.","question":"ما الذي سبق نشر اللوحة التعليمية في المثال؟","correct":"مراجعة دقة المعلومات ومصدرها","wrong":["إخفاء المراجع","تجريب علاج","إضافة أرقام متخيلة"],"practice":"بعد قراءة النص المقرر، استخرج حجة موثقة حول العلاقة بين المعرفة والتطبيق مع تحليلها.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":6,"title":"المقاييس عند العرب","passage":"تختلف وحدات القياس التاريخية باختلاف المكان والزمن والمادة التي تقاس، ولذلك لا يصح تحويل كل وحدة قديمة إلى قيمة حديثة ثابتة دون تحديد مرجعها. في مثال مستقل يوثق باحث الاسم التاريخي للوحدة قبل مقارنته بوحدة معيارية معاصرة.","question":"لماذا يجب تحديد مصدر وحدة قياس قديمة قبل تحويلها؟","correct":"لأن قيمتها قد تختلف باختلاف السياق","wrong":["لأن كل القياسات وهم","لأن الحساب ممنوع","لأن كل الوحدات متساوية"],"practice":"اختر وحدة تاريخية موثقة، واذكر موضع استخدامها وحدود أي تحويل مقترح إلى نظام حديث.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"53fb9e9c-5690-4a1d-8eef-5ae1cc9a103c","n":7,"title":"مهارة التحليل والتعليق","passage":"التحليل يحدد القضية والعناصر والعلاقات بينها، أما التعليق فيقدم موقفًا معللًا بعد عرض الدليل. في نص مستقل يصف طالب تجربة مقارنة مصدرين؛ يحلل اختلاف المعلومتين، ثم يعلق على سبب ترجيح المصدر الأوثق. لا يكفي قول «أعجبني» دون تفسير.","question":"ما الذي يميز التعليق المقنع عن الانطباع المجرد؟","correct":"الحكم المعلل بشواهد واضحة","wrong":["تكرار العنوان","نسخ النص كله","إخفاء الرأي المقابل"],"practice":"اكتب تحليلًا من فقرة وتعليقًا من فقرة على مادة تعليمية موثقة مع الفصل بين الملاحظة والحكم.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":1,"title":"مقدمة عن الشعر القديم","passage":"تتنوع القصائد القديمة في الأغراض والأساليب بحسب الشاعر والعصر، وتحتاج دراسة النص الصحيح إلى مصدر محقق قبل الحديث عن القافية أو مناسبة القصيدة. لا نساوي كل صورة شعرية بواقعة تاريخية، وننظر إلى الصوت الشعري والبناء والعاطفة معًا.","question":"ما الخطوة اللازمة قبل نسبة بيت لشاعر قديم؟","correct":"التحقق من نص محقق ومصدر موثوق","wrong":["تأليف بيت مشابه","الاعتماد على العنوان","اختيار قافية عشوائية"],"practice":"اختر قصيدة صحيحة النسبة وحلل غرضها ومطلعها مع توثيق الشاهد.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":2,"title":"أفعال المدح والذم","passage":"«نِعْمَ» و«بِئْسَ» من الأفعال الجامدة المستخدمة في المدح والذم، ويحتاج التحليل إلى معرفة الفاعل والمخصوص بالمدح أو الذم. في «نِعْمَ الخُلُقُ الصدقُ» ندرس بناء الأسلوب وفق القاعدة لا بوصفه جملة فعلية عادية فقط.","question":"ما الفعل الذي يفيد المدح؟","correct":"نِعْمَ","wrong":["بِئْسَ","ليس","لن"],"practice":"كوّن جملتين للمدح وجملتين للذم وحدد الفاعل والمخصوص في كل مثال.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":3,"title":"الوصف عند النابغة الذبياني","passage":"لا يمكن تحديد صورة من شعر النابغة الذبياني من عنوان «الوصف» وحده أو كتابة بيت ونسبته إليه. تدريب مستقل: «امتد الطريق كخيط من ضوء أمام المسافر» تشبيه جديد يصور مكانًا؛ يستخدم للتمييز بين الصورة الحسية والغرض دون أن يمثل شعر الشاعر.","question":"ما الأسلوب في «الطريق كخيط من ضوء»؟","correct":"تشبيه لوجود الكاف","wrong":["جناس","استفهام","طباق"],"practice":"استخرج بيتًا موثقًا للنابغة يصف مشهدًا، واشرح الصورة وأثرها وقارنها بالتشبيه الأصلي.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":4,"title":"بحر الطويل","passage":"تقوم الصيغة التامة المشهورة للبحر الطويل على «فعولن مفاعيلن فعولن مفاعيلن» لكل شطر في الأصل، مع صور الزحاف والعلة المعروفة. يتطلب التقطيع كتابة عروضية منضبطة تراعي المنطوق، ولا يُعرف البحر من عدد كلمات البيت.","question":"ما أول تفعيلة في نسق البحر الطويل؟","correct":"فعولن","wrong":["متفاعلن","مستفعلن","فاعلاتن"],"practice":"اختر بيتًا موثقًا على البحر الطويل وقطعه مع بيان موضع تغيير إن وجد.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":5,"title":"زارت عليّ","passage":"عنوان «زارت عليّ» لا يحدد المتكلم أو المناسبة أو صاحب النص دون نسخة معتمدة، ولذلك لا يؤلف ضاديوم أبياتًا منسوبة إليه. في مثال نثري أصلي يستقبل راو زائرًا مفاجئًا ويعيد ترتيب توقعاته؛ يمكن تحليله في ضوء الحدث المفاجئ دون ربطه بالقصيدة.","question":"ما المطلوب لتحديد المخاطب والعاطفة في القصيدة؟","correct":"الأبيات الموثقة وقرائن السياق","wrong":["تخمين من العنوان","اختلاق مقطع شعري","حكم على الاسم وحده"],"practice":"استخرج من النص المقرر شاهدًا موثقًا للمشاعر، ثم فسر تغير المعنى عبر بيتين.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":6,"title":"بحر البسيط","passage":"في صورته التامة الأصلية يتكون البسيط من «مستفعلن فاعلن مستفعلن فاعلن» في كل شطر، وقد تطرأ تغييرات عروضية. يحتاج التقطيع إلى التمييز بين المكتوب والمنطوق ومراعاة الحركات والشدة والمد.","question":"ما التفعيلة الأولى في البحر البسيط؟","correct":"مستفعلن","wrong":["فعولن","مفاعلتن","فاعلاتن"],"practice":"اختر شطرًا معروف المصدر على البسيط واكتبه كتابة عروضية ثم طابق التفعيلات.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"504c7432-f908-4994-8a50-29e09d1aa137","n":7,"title":"مهارة تصميم موضوع","passage":"يصمم الكاتب موضوعًا محدد الغاية عبر مخطط يبدأ بالسؤال أو الفكرة الرئيسة، ثم عناوين فرعية وشواهد وخاتمة. في نموذج مستقل يريد طالب الكتابة عن أهمية مراجعة المصادر، فيحدد ثلاثة أسباب ومثالًا لكل سبب قبل صياغة المقدمة.","question":"ما الذي يساعد على ترابط الموضوع قبل الكتابة؟","correct":"مخطط أفكار مرتب حسب الغاية","wrong":["جمع أفكار متناقضة بلا صلة","إلغاء الأطروحة","نسخ مقدمات جاهزة"],"practice":"صمم مخططًا لموضوع من ثلاثة محاور مع دليل وخاتمة دون كتابة نص جاهز منسوخ.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"8af552b8-7ee4-408f-a58c-094bffa2c7ee","n":1,"title":"الهوية الثقافية","passage":"تشمل الهوية الثقافية اللغة والممارسات والذاكرة ومظاهر التعبير، لكنها ليست قالبًا ثابتًا لكل فرد. في مثال مستقل ينظم طلاب معرضًا لغويًا يعرض تعبيرات محلية ويقارن معانيها بالفصحى، دون الادعاء أنها تمثل جميع السكان.","question":"ما الممارسة المناسبة لدراسة مظهر ثقافي؟","correct":"التوثيق والمقارنة دون تعميم","wrong":["اختراع عادات","إلغاء اختلاف الأفراد","الاعتماد على مثال واحد مطلق"],"practice":"اكتب فقرة عن مظهر ثقافي موثق مع مثال وحدود تعميمه.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"8af552b8-7ee4-408f-a58c-094bffa2c7ee","n":2,"title":"مراجعة الصيغ الصرفية","passage":"الصيغ الصرفية تتضمن اسم الفاعل والمفعول والمصدر وغيرها، ويفهمها الطالب برد الكلمة إلى فعلها وجذرها وسياقها. «كاتب» من «كتب» اسم فاعل و«مكتوب» اسم مفعول، بينما «كتابة» مصدر.","question":"ما الصيغة الصرفية لـ«مكتوب»؟","correct":"اسم مفعول","wrong":["اسم فاعل","حرف جر","فعل أمر"],"practice":"استخرج خمس صيغ صرفية من فقرة عربية موثوقة مع أوزانها ودلالاتها.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"8af552b8-7ee4-408f-a58c-094bffa2c7ee","n":3,"title":"العولمة","passage":"تتصل العولمة بتوسع التبادل الاقتصادي والثقافي والتقني بين مجتمعات مختلفة، وقد تحمل فرصًا وتحديات لا تظهر على نحو متماثل للجميع. في مثال مستقل يتعاون فريق مدرسي مع طلاب من بلد آخر عبر مشروع قراءة ويواجه مشكلة اختلاف المواعيد.","question":"ما الفائدة التي عرضها المثال للتعاون الدولي؟","correct":"تبادل خبرات القراءة","wrong":["إلغاء كل الثقافات","ضمان نجاح بلا تخطيط","منع الحوار"],"practice":"اكتب مقالًا قصيرًا يوازن بين فرصة وتحدٍّ للتواصل العالمي بدليل ومثال مستقل.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"8af552b8-7ee4-408f-a58c-094bffa2c7ee","n":4,"title":"الانفجار الديمغرافي","passage":"لا يُفهم تغير عدد السكان دون بيانات مؤرخة ومنهج حساب واضح؛ يجب التمييز بين العدد الإجمالي ومعدل النمو والتوزيع العمري. في تمرين أصلي يناقش فريق أثر تغير سكان منطقة على احتياجات المدارس، دون اختلاق إحصاءات رسمية.","question":"ما المصدر اللازم لإثبات تغير معدل النمو السكاني؟","correct":"بيانات إحصائية من جهة موثوقة","wrong":["انطباع فردي","صورة دون تاريخ","حوار متخيل"],"practice":"حلل رسمًا بيانيًا منشورًا في مرجع رسمي مع ذكر السنة والقياس وحدود الاستنتاج.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"},{"cid":"91a1e4cb-5263-4c69-abb1-8169ea412e6f","unit":"8af552b8-7ee4-408f-a58c-094bffa2c7ee","n":5,"title":"مهارة إلقاء العرض الشفهي","passage":"يحتاج العرض الشفهي إلى مقدمة تحدد الموضوع، ومحورين مدعومين بدليل، وخاتمة موجزة، مع ضبط الوقت والنظر إلى الجمهور. في مثال مستقل يعرض طالب نتائج قراءة كتابين ولا ينسب إليهما أفكارًا لم ترد فيهما.","question":"ما العنصر الذي يعزز مصداقية العرض؟","correct":"شواهد واضحة ومصادر دقيقة","wrong":["رفع الصوت وحده","الإطالة دون موضوع","إخفاء مصادر المعلومات"],"practice":"حضّر عرضًا دقيقتين مع مقدمة ودليلين وخاتمة ثم قيم وضوح الصوت والتسلسل.","old":"DADYOOM_MR_G11_SCIENTIFIC_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=11 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G11_SCIENCE_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G11_SCIENCE_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G11_SCIENCE_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G11_SCIENCE_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_SCIENCE_ORIGINAL_24_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_SCIENCE_ORIGINAL_24_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_SCIENCE_ORIGINAL_24_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G11_SCIENCE_ORIGINAL_24_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G11_SCIENCE_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;